const crypto = require('crypto');

function canonical(value) {
  if (Array.isArray(value)) return '[' + value.map(canonical).join(',') + ']';
  if (value && typeof value === 'object') {
    return '{' + Object.keys(value).sort().map(k => JSON.stringify(k) + ':' + canonical(value[k])).join(',') + '}';
  }
  return JSON.stringify(value);
}

function pick(object, paths) {
  for (const path of paths) {
    if (object && Object.prototype.hasOwnProperty.call(object, path) && object[path] !== '') return object[path];
    let current = object;
    for (const part of path.split('.')) current = current && typeof current === 'object' ? current[part] : undefined;
    if (current !== undefined && current !== null && current !== '') return current;
  }
  return null;
}

const headers = $json.headers || {};
const envelope = $json.body || {};
const timestamp = String(headers['x-sanolifood-timestamp'] || '');
const supplied = String(headers['x-sanolifood-signature'] || '');
if (!/^\d{10}$/.test(timestamp)) throw new Error('Missing or invalid integration timestamp');
if (Math.abs(Math.floor(Date.now() / 1000) - Number(timestamp)) > 300) throw new Error('Integration request is outside the five-minute replay window');
if (envelope.schema_version !== 1 || envelope.integration !== 'sanolifood-wazuh' || typeof envelope.alert_json !== 'string') throw new Error('Unsupported Wazuh integration envelope');
const secret = String($env.SOAR_WEBHOOK_SECRET || '');
if (secret.length < 32) throw new Error('SOAR webhook secret is unavailable');
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + canonical(envelope)).digest('hex');
const expectedBuffer = Buffer.from(expected);
const suppliedBuffer = Buffer.from(supplied);
if (expectedBuffer.length !== suppliedBuffer.length || !crypto.timingSafeEqual(expectedBuffer, suppliedBuffer)) throw new Error('Invalid Wazuh integration signature');

const triage = {
  '110011': ['PB-AUTH-001', 'critical'], '110012': ['PB-AUTH-001', 'critical'],
  '110020': ['PB-BUS-001', 'high'], '110030': ['PB-QUALITY-001', 'high'],
  '110040': ['PB-APP-001', 'medium'], '110100': ['PB-NDR-VALIDATION-001', 'low'],
  '110110': ['PB-NDR-RECON-001', 'high'], '110120': ['PB-NDR-RECON-001', 'high'],
  '110130': ['PB-NDR-SQLI-001', 'critical'], '110140': ['PB-NDR-RECON-001', 'high'],
  '110200': ['PB-ENDPOINT-VALIDATION-001', 'low'], '110220': ['PB-ENDPOINT-VALIDATION-001', 'low'],
  '110210': ['PB-ENDPOINT-FIM-001', 'critical'], '110211': ['PB-ENDPOINT-FIM-001', 'critical']
};
if (envelope.alert_json.length > 1048576) throw new Error('Wazuh alert exceeds the accepted size');
let alert;
try { alert = JSON.parse(envelope.alert_json); } catch { throw new Error('Wazuh alert JSON is invalid'); }
if (!alert || typeof alert !== 'object' || Array.isArray(alert)) throw new Error('Wazuh alert must be a JSON object');
const ruleId = Number(pick(alert, ['rule.id']));
const policy = triage[String(ruleId)];
if (!policy) throw new Error('Wazuh rule is not routed by the SOAR catalog');
const agentId = pick(alert, ['agent.id']);
const agentName = pick(alert, ['agent.name']);
const sourceIp = pick(alert, ['data.src_ip', 'data.srcip', 'data.source_ip', 'data.source.ip', 'srcip']);
const actorUsername = pick(alert, ['data.actor_username', 'data.audit.user.name', 'data.win.eventdata.user', 'data.win.system.userID']);
const resourcePath = pick(alert, ['syscheck.path', 'data.path', 'data.file', 'data.win.eventdata.targetFilename']);
const detectedAt = String(pick(alert, ['timestamp']) || envelope.sent_at);
const sourceAlertId = pick(alert, ['id']);
const ruleDescription = String(pick(alert, ['rule.description']) || 'Wazuh security alert');
const ruleLevel = Number(pick(alert, ['rule.level']) || 0);
const material = [sourceAlertId, ruleId, agentId, detectedAt, sourceIp, actorUsername, resourcePath].map(v => String(v || '')).join('|');
const dedupKey = crypto.createHash('sha256').update(material).digest('hex');

return [{ json: {
  schema_version: 1, workflow_version: '0.7.0', dedup_key: dedupKey, source_alert_id: sourceAlertId ? String(sourceAlertId) : null,
  rule_id: ruleId, rule_level: ruleLevel, rule_description: ruleDescription, priority: policy[1], playbook_id: policy[0],
  agent_id: agentId ? String(agentId) : null, agent_name: agentName ? String(agentName) : null, source_ip: sourceIp ? String(sourceIp) : null,
  actor_username: actorUsername ? String(actorUsername).toLowerCase() : null, resource_path: resourcePath ? String(resourcePath) : null,
  detected_at: detectedAt, received_at: new Date().toISOString(), raw_alert: alert
} }];
